import { Pool } from 'pg';

// ─────────────────────────────────────────────────────────────────────────────
// Power Quality Health Check — NRS 048-2 compliance assessment + equipment risk.
//
// This is deliberately DETERMINISTIC: every number here is measured or derived
// from a published standard, never generated by a model. The AI layer narrates
// this output; it does not produce it. That distinction is what makes the report
// defensible in front of an engineer, an insurer, or a municipality.
//
// Assessment method follows the standard's convention of judging a parameter on
// the 95th percentile of readings over an observation window (typically 1 week),
// rather than on worst-case instantaneous excursions.
// ─────────────────────────────────────────────────────────────────────────────

export type Status = 'PASS' | 'WARN' | 'FAIL' | 'NO_DATA';
export type Severity = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';

export type Trend = 'IMPROVING' | 'STABLE' | 'DEGRADING' | 'NO_BASELINE';

export interface ComplianceParameter {
    key:      string;
    label:    string;
    measured: number | null;
    display:  string;          // pre-formatted measured value with unit
    limit:    string;          // human-readable limit
    status:   Status;
    standard: string;          // which standard/clause this is judged against
    method:   string;          // how it was measured
    detail:   string;          // plain-language interpretation
    previous: number | null;   // same metric, preceding window
    trend:    Trend;
    trend_note: string;        // e.g. "up from 12.1% last period"
}

export interface EquipmentRisk {
    key:       string;
    severity:  Severity;
    title:     string;
    finding:   string;   // what the data shows
    mechanism: string;   // WHY it damages equipment (the engineering)
    action:    string;   // what to do about it
    standard:  string;
}

export interface ComplianceReport {
    meter_id:      string;
    meter_name:    string;
    site_name:     string;
    period_days:   number;
    readings:      number;
    from:          string;
    to:            string;
    verdict:       'COMPLIANT' | 'COMPLIANT_WITH_RISK' | 'NON_COMPLIANT' | 'INSUFFICIENT_DATA';
    verdict_note:  string;
    parameters:    ComplianceParameter[];
    risks:         EquipmentRisk[];
    supply_score:  number;   // 0-100, quality of the incoming supply (utility's responsibility)
    install_score: number;   // 0-100, quality of the client's installation (client's responsibility)
    /** Period-over-period movement — what continuous monitoring buys you. */
    has_baseline:  boolean;
    trend_summary: string;
    degrading:     string[]; // labels of parameters that got materially worse
}

// SA LV nominal: 230 V phase-neutral, ±10% → 207–253 V
const V_NOM = 230, V_MIN = 207, V_MAX = 253;
const THD_LIMIT = 8;        // NRS 048-2 LV compatibility level (%)
const UNBALANCE_LIMIT = 2;  // NRS 048-2 voltage unbalance compatibility level (%)
const F_MIN = 49, F_MAX = 51;
const PF_TARGET = 0.95;     // typical SA utility target before reactive charges
const I_UNBALANCE_GUIDE = 10; // NEMA guidance: investigate current unbalance >10%

// Current distortion is judged on IEEE 519, not NRS 048-2 — NRS 048-2 sets
// VOLTAGE compatibility levels; current distortion limits are IEEE 519's.
// IEEE 519 limits TDD by the short-circuit ratio (Isc/IL) at the point of common
// coupling, ranging 5% (stiff supply) to 20% (weak supply). Isc requires the
// transformer impedance and the utility fault level, neither of which is
// knowable from telemetry — so we only assert non-compliance above 20%, where
// the site breaches the most permissive band whatever the ratio turns out to be.
const TDD_STRICTEST = 5;    // IEEE 519 limit at Isc/IL < 20
const TDD_LOOSEST   = 20;   // IEEE 519 limit at Isc/IL > 1000
const I_LOAD_FLOOR  = 0.25; // assess THD-I only above 25% of peak load current

/**
 * NEMA MG-1 motor derating for voltage unbalance. Winding temperature rise is
 * approximately 2 x (% unbalance)^2, so even small unbalance is disproportionately
 * damaging. Returns the fraction of nameplate output the motor can safely deliver.
 */
export function nemaDerate(unbalancePct: number): number {
    if (unbalancePct <= 1) return 1.00;
    if (unbalancePct <= 2) return 0.95;
    if (unbalancePct <= 3) return 0.89;
    if (unbalancePct <= 4) return 0.82;
    if (unbalancePct <= 5) return 0.75;
    return 0.70;
}

/** Approximate winding temperature rise (%) from voltage unbalance — NEMA MG-1. */
export function windingTempRisePct(unbalancePct: number): number {
    return 2 * unbalancePct * unbalancePct;
}

/**
 * Compare a metric against the same metric in the preceding window.
 *
 * `higherIsBetter` encodes the direction of "good" per metric (voltage-in-band %
 * up is good; THD up is bad). A 10% relative change is required before calling a
 * movement real — below that it is sampling noise, and crying wolf on noise is
 * how a monitoring product loses credibility.
 */
function compareTrend(
    current: number | null,
    previous: number | null,
    higherIsBetter: boolean,
    unit: string,
    decimals = 2,
    // Names the quantity actually being compared. Needed where the displayed value
    // differs from the compared statistic — the voltage row shows a range in volts
    // but is judged on the percentage of readings inside the band, and quoting a
    // percentage next to a voltage range reads as an error.
    metricLabel = '',
): { trend: Trend; note: string } {
    if (current === null || previous === null || !isFinite(previous) || previous === 0) {
        return { trend: 'NO_BASELINE', note: 'No comparable prior period yet — this reading becomes the baseline.' };
    }
    const delta = current - previous;
    const relative = Math.abs(delta / previous);
    const fmt = (v: number) => `${v.toFixed(decimals)}${unit}`;
    const subject = metricLabel ? `${metricLabel} ` : '';

    if (relative < 0.10) {
        return { trend: 'STABLE', note: `${subject}${fmt(current)} — steady (was ${fmt(previous)} last period).` };
    }
    const improved = higherIsBetter ? delta > 0 : delta < 0;
    return {
        trend: improved ? 'IMPROVING' : 'DEGRADING',
        note: `${subject}${fmt(current)} — ${improved ? 'improved' : 'worsened'} from ${fmt(previous)} last period.`,
    };
}

export async function assessPowerQuality(
    pool:    Pool,
    meterId: string,
    days:    number = 7,
): Promise<ComplianceReport | null> {
    const client = await pool.connect();
    try {
        const meta = await client.query(
            `SELECT m.name AS meter_name, s.name AS site_name
             FROM meters m JOIN sites s ON m.site_id = s.id WHERE m.id = $1`,
            [meterId]
        );
        if (meta.rows.length === 0) return null;

        // Metrics for one observation window, expressed as an offset from now.
        // Running this for the current window AND the one immediately before it is
        // what turns a point-in-time audit into degradation tracking — the whole
        // reason continuous monitoring is worth more than a one-off survey.
        const windowMetrics = (startDaysAgo: number, endDaysAgo: number) => client.query(`
            WITH base AS (
                SELECT time, voltage_a, voltage_b, voltage_c,
                       current_a, current_b, current_c,
                       power_factor_total, thd_voltage_a, thd_current_a, frequency, power_active_total,
                       NULLIF((COALESCE(voltage_a,0)+COALESCE(voltage_b,0)+COALESCE(voltage_c,0))/3.0, 0) AS v_avg,
                       NULLIF((COALESCE(current_a,0)+COALESCE(current_b,0)+COALESCE(current_c,0))/3.0, 0) AS i_avg
                FROM meter_readings
                WHERE meter_id = $1
                  AND time >= NOW() - ($2 || ' days')::INTERVAL
                  AND time <  NOW() - ($7 || ' days')::INTERVAL
            ), calc AS (
                SELECT *,
                    CASE WHEN v_avg IS NOT NULL AND voltage_b IS NOT NULL AND voltage_c IS NOT NULL
                         THEN GREATEST(ABS(voltage_a-v_avg),ABS(voltage_b-v_avg),ABS(voltage_c-v_avg))/v_avg*100 END AS v_unb,
                    CASE WHEN i_avg IS NOT NULL AND current_b IS NOT NULL AND current_c IS NOT NULL
                         THEN GREATEST(ABS(current_a-i_avg),ABS(current_b-i_avg),ABS(current_c-i_avg))/i_avg*100 END AS i_unb,
                    -- Peak load current over the window. Stands in for maximum
                    -- demand current when estimating TDD below.
                    MAX(i_avg) OVER () AS i_peak
                FROM base
            )
            SELECT
                COUNT(*)                                                            AS n,
                MIN(time)                                                           AS t_from,
                MAX(time)                                                           AS t_to,
                MIN(voltage_a)                                                      AS v_min,
                MAX(voltage_a)                                                      AS v_max,
                percentile_cont(0.95) WITHIN GROUP (ORDER BY voltage_a)             AS v_p95,
                percentile_cont(0.05) WITHIN GROUP (ORDER BY voltage_a)             AS v_p05,
                100.0*SUM(CASE WHEN voltage_a BETWEEN $3 AND $4 THEN 1 ELSE 0 END)
                    / NULLIF(COUNT(voltage_a),0)                                    AS v_in_band_pct,
                SUM(CASE WHEN voltage_a < $3 THEN 1 ELSE 0 END)                     AS dip_count,
                SUM(CASE WHEN voltage_a > $4 THEN 1 ELSE 0 END)                     AS swell_count,
                percentile_cont(0.95) WITHIN GROUP (ORDER BY thd_voltage_a)         AS thd_p95,
                MAX(thd_voltage_a)                                                  AS thd_max,
                percentile_cont(0.95) WITHIN GROUP (ORDER BY v_unb)                 AS v_unb_p95,
                percentile_cont(0.95) WITHIN GROUP (ORDER BY i_unb)                 AS i_unb_p95,
                AVG(i_unb)                                                          AS i_unb_avg,
                AVG(power_factor_total)                                             AS pf_avg,
                MIN(power_factor_total)                                             AS pf_min,
                MIN(frequency)                                                      AS f_min,
                MAX(frequency)                                                      AS f_max,
                100.0*SUM(CASE WHEN frequency BETWEEN $5 AND $6 THEN 1 ELSE 0 END)
                    / NULLIF(COUNT(frequency),0)                                    AS f_in_band_pct,
                MAX(power_active_total)                                             AS peak_kw,
                AVG(power_active_total)                                             AS avg_kw,
                AVG(current_a) AS ia, AVG(current_b) AS ib, AVG(current_c) AS ic,
                -- Current distortion. THD-I is misleading at light load: a small
                -- absolute harmonic content is a large fraction of a small
                -- fundamental, so an idling site reads as badly distorted. It is
                -- therefore only assessed above a load floor. TDD rescales it
                -- against peak demand current, which is what IEEE 519 limits.
                percentile_cont(0.95) WITHIN GROUP (ORDER BY thd_current_a)
                    FILTER (WHERE i_avg >= $8 * i_peak)                              AS thd_i_p95,
                COUNT(thd_current_a) FILTER (WHERE i_avg >= $8 * i_peak)             AS thd_i_n,
                percentile_cont(0.95) WITHIN GROUP (
                    ORDER BY thd_current_a * i_avg / NULLIF(i_peak, 0))               AS tdd_p95,
                MAX(i_peak)                                                          AS i_peak
            FROM calc
        `, [meterId, startDaysAgo, V_MIN, V_MAX, F_MIN, F_MAX, endDaysAgo, I_LOAD_FLOOR]);

        // Current window, and the equal-length window immediately preceding it.
        const [q, qPrev] = await Promise.all([
            windowMetrics(days, 0),
            windowMetrics(days * 2, days),
        ]);

        const r = q.rows[0];
        const p = qPrev.rows[0];
        const n = Number(r.n) || 0;
        const nPrev = Number(p?.n) || 0;

        const num = (v: any): number | null => (v === null || v === undefined ? null : Number(v));

        const vP95   = num(r.v_p95);
        const vP05   = num(r.v_p05);
        const vMin   = num(r.v_min);
        const vMax   = num(r.v_max);
        const vBand  = num(r.v_in_band_pct);
        const thdP95 = num(r.thd_p95);
        const vUnb   = num(r.v_unb_p95);
        const iUnb   = num(r.i_unb_p95);
        const iUnbAvg = num(r.i_unb_avg);
        const pfAvg  = num(r.pf_avg);
        const fMin   = num(r.f_min);
        const fMax   = num(r.f_max);
        const fBand  = num(r.f_in_band_pct);
        const dips   = Number(r.dip_count) || 0;
        const swells = Number(r.swell_count) || 0;
        const peakKw = num(r.peak_kw);
        const ia = num(r.ia), ib = num(r.ib), ic = num(r.ic);
        const thdIP95 = num(r.thd_i_p95);
        const tddP95  = num(r.tdd_p95);
        const thdIN   = Number(r.thd_i_n) || 0;
        const iPeak   = num(r.i_peak);

        // Preceding-window baselines. Require a reasonable sample count before
        // treating the prior period as a valid comparison.
        const hasBaseline = nPrev >= 100;
        const prev = (col: string): number | null => (hasBaseline ? num(p[col]) : null);
        const pvBand  = prev('v_in_band_pct');
        const pThd    = prev('thd_p95');
        const pThdI   = prev('thd_i_p95');
        const pVUnb   = prev('v_unb_p95');
        const pIUnb   = prev('i_unb_p95');
        const pPf     = prev('pf_avg');
        const pFBand  = prev('f_in_band_pct');

        const tVolt = compareTrend(vBand,  pvBand, true,  '%', 1, 'Readings inside band:');
        const tThd  = compareTrend(thdP95, pThd,   false, '%', 2);
        const tUnb  = compareTrend(vUnb,   pVUnb,  false, '%', 2);
        const tFreq = compareTrend(fBand,  pFBand, true,  '%', 1, 'Readings inside band:');
        const tPf   = compareTrend(pfAvg,  pPf,    true,  '', 3);
        const tIUnb = compareTrend(iUnb,   pIUnb,  false, '%', 1, 'Current imbalance:');
        const tThdI = compareTrend(thdIP95, pThdI, false, '%', 1, 'Current distortion:');

        if (n < 100) {
            return {
                meter_id: meterId,
                meter_name: meta.rows[0].meter_name,
                site_name:  meta.rows[0].site_name,
                period_days: days, readings: n,
                from: r.t_from ?? '', to: r.t_to ?? '',
                verdict: 'INSUFFICIENT_DATA',
                verdict_note: `Only ${n} readings in the last ${days} days. A minimum of 100 is needed for a statistically meaningful assessment; a full 7-day observation window is recommended.`,
                parameters: [], risks: [], supply_score: 0, install_score: 0,
                has_baseline: false,
                trend_summary: 'Not enough data to establish a baseline yet.',
                degrading: [],
            };
        }

        // ── Supply-side compliance parameters (the utility's responsibility) ──
        const parameters: ComplianceParameter[] = [];

        parameters.push({
            key: 'voltage',
            label: 'Voltage magnitude',
            measured: vBand,
            display: vMin !== null && vMax !== null ? `${vMin.toFixed(1)}–${vMax.toFixed(1)} V` : '—',
            limit: `${V_MIN}–${V_MAX} V (230 V ±10%)`,
            status: vBand === null ? 'NO_DATA' : vBand >= 95 ? 'PASS' : vBand >= 90 ? 'WARN' : 'FAIL',
            standard: 'NRS 048-2 — LV voltage magnitude compatibility level',
            method: `${n.toLocaleString()} readings over ${days} days; 5th–95th percentile ${vP05?.toFixed(1)}–${vP95?.toFixed(1)} V`,
            detail: vBand !== null && vBand >= 95
                ? `${vBand.toFixed(1)}% of readings fell inside the statutory band. Supply voltage is compliant.`
                : `Only ${vBand?.toFixed(1)}% of readings fell inside the statutory band — the supply is outside NRS 048-2 limits and is the utility's responsibility to correct.`,
            previous: pvBand, trend: tVolt.trend, trend_note: tVolt.note,
        });

        parameters.push({
            key: 'thd',
            label: 'Voltage THD (harmonic distortion)',
            measured: thdP95,
            display: thdP95 !== null ? `${thdP95.toFixed(2)}%` : '—',
            limit: `≤ ${THD_LIMIT}%`,
            status: thdP95 === null ? 'NO_DATA' : thdP95 <= 5 ? 'PASS' : thdP95 <= THD_LIMIT ? 'WARN' : 'FAIL',
            standard: 'NRS 048-2 — total harmonic distortion compatibility level',
            method: '95th percentile of measured voltage THD',
            detail: thdP95 === null ? 'No THD data.'
                : thdP95 <= 5 ? `Distortion is low. No harmonic mitigation is justified at this level.`
                : thdP95 <= THD_LIMIT ? `Distortion is elevated but still within the ${THD_LIMIT}% limit. Worth monitoring, particularly if inverters or VSDs are added.`
                : `Distortion exceeds the ${THD_LIMIT}% compatibility level. Expect additional heating in transformers, cables and capacitors.`,
            previous: pThd, trend: tThd.trend, trend_note: tThd.note,
        });

        // Current distortion. Judged against IEEE 519 rather than NRS 048-2, and
        // deliberately non-committal about the exact limit: that depends on the
        // short-circuit ratio, which telemetry cannot see. Asserting a limit we
        // cannot derive would be the fastest way to lose an engineer's trust.
        const tddKnowable = thdIP95 !== null && tddP95 !== null && thdIN >= 20;
        parameters.push({
            key: 'current_distortion',
            label: 'Current distortion (THD-I)',
            measured: tddP95,
            display: thdIP95 !== null ? `${thdIP95.toFixed(1)}%` : '—',
            limit: `TDD ${TDD_STRICTEST}–${TDD_LOOSEST}% (IEEE 519, by supply strength)`,
            status: !tddKnowable ? 'NO_DATA'
                : tddP95! <= TDD_STRICTEST ? 'PASS'
                : tddP95! > TDD_LOOSEST    ? 'FAIL'
                : 'WARN',
            standard: 'IEEE 519 — current distortion at the point of common coupling',
            method: thdIN > 0
                ? `95th percentile of ${thdIN.toLocaleString()} readings taken above ${(I_LOAD_FLOOR * 100).toFixed(0)}% of the ${iPeak?.toFixed(0) ?? '—'} A peak load current`
                : 'Insufficient readings at meaningful load',
            detail: !tddKnowable
                ? 'Not enough current-distortion data at meaningful load to assess. THD-I measured at light load is not comparable against any limit.'
                : tddP95! <= TDD_STRICTEST
                    ? `Demand distortion of about ${tddP95!.toFixed(1)}% sits inside the strictest IEEE 519 band, so this installation is compliant regardless of how stiff or weak the supply is.`
                : tddP95! > TDD_LOOSEST
                    ? `Demand distortion of about ${tddP95!.toFixed(1)}% exceeds ${TDD_LOOSEST}%, which is IEEE 519's most permissive limit. This breaches the standard whatever the short-circuit ratio at your point of supply.`
                    : `Measured THD-I is ${thdIP95!.toFixed(1)}%, which works out to roughly ${tddP95!.toFixed(1)}% demand distortion (TDD). Whether that complies depends on the short-circuit ratio at your point of supply — resolving it needs the supply transformer rating and the utility fault level.`,
            previous: pThdI, trend: tThdI.trend, trend_note: tThdI.note,
        });

        parameters.push({
            key: 'unbalance',
            label: 'Voltage unbalance',
            measured: vUnb,
            display: vUnb !== null ? `${vUnb.toFixed(2)}%` : '—',
            limit: `≤ ${UNBALANCE_LIMIT}%`,
            status: vUnb === null ? 'NO_DATA' : vUnb <= UNBALANCE_LIMIT ? 'PASS' : vUnb <= 3 ? 'WARN' : 'FAIL',
            standard: 'NRS 048-2 — voltage unbalance compatibility level',
            method: '95th percentile; NEMA definition (max deviation from mean ÷ mean)',
            detail: vUnb === null ? 'Three-phase voltage data unavailable.'
                : vUnb <= UNBALANCE_LIMIT ? 'Phase voltages are well balanced at the point of supply.'
                : `Voltage unbalance exceeds ${UNBALANCE_LIMIT}%. Motors on this supply are being derated and will run hot (see equipment risk).`,
            previous: pVUnb, trend: tUnb.trend, trend_note: tUnb.note,
        });

        parameters.push({
            key: 'frequency',
            label: 'Frequency',
            measured: fBand,
            display: fMin !== null && fMax !== null ? `${fMin.toFixed(2)}–${fMax.toFixed(2)} Hz` : '—',
            limit: `${F_MIN}–${F_MAX} Hz`,
            status: fBand === null ? 'NO_DATA' : fBand >= 99 ? 'PASS' : fBand >= 95 ? 'WARN' : 'FAIL',
            standard: 'NRS 048-2 — system frequency',
            method: `Full range observed across ${days} days`,
            detail: fBand !== null && fBand >= 99
                ? 'Grid frequency held within the normal operating band throughout.'
                : `Frequency left the ${F_MIN}–${F_MAX} Hz band during the period — an indicator of grid stress events.`,
            previous: pFBand, trend: tFreq.trend, trend_note: tFreq.note,
        });

        parameters.push({
            key: 'power_factor',
            label: 'Power factor',
            measured: pfAvg,
            display: pfAvg !== null ? pfAvg.toFixed(3) : '—',
            limit: `≥ ${PF_TARGET} (tariff target)`,
            status: pfAvg === null ? 'NO_DATA' : pfAvg >= PF_TARGET ? 'PASS' : pfAvg >= 0.90 ? 'WARN' : 'FAIL',
            standard: 'Tariff condition (not a NRS 048-2 quality-of-supply parameter)',
            method: `Mean of ${n.toLocaleString()} readings`,
            detail: pfAvg === null ? 'No power factor data.'
                : pfAvg >= PF_TARGET ? 'Power factor meets the typical utility target; no reactive penalty exposure.'
                : `Power factor is below the ${PF_TARGET} target — most SA utilities levy reactive energy or kVA demand charges at this level.`,
            previous: pPf, trend: tPf.trend, trend_note: tPf.note,
        });

        // ── Equipment risk (the client's installation — where the money is) ──
        const risks: EquipmentRisk[] = [];

        // Current unbalance: the single most under-diagnosed installation fault.
        if (iUnb !== null && iUnb > I_UNBALANCE_GUIDE) {
            const severity: Severity = iUnb > 30 ? 'CRITICAL' : iUnb > 20 ? 'HIGH' : 'MEDIUM';
            // Low voltage unbalance + high current unbalance ⇒ the fault is load
            // distribution inside the installation, not the incoming supply.
            const loadSide = vUnb !== null && vUnb <= UNBALANCE_LIMIT;
            const phases = (ia !== null && ib !== null && ic !== null)
                ? ` (L1 ${ia.toFixed(0)} A / L2 ${ib.toFixed(0)} A / L3 ${ic.toFixed(0)} A average)`
                : '';
            risks.push({
                key: 'current_unbalance',
                severity,
                title: 'Phase current imbalance is stressing three-phase equipment',
                // Report both statistics: the p95 is the assessment figure, but quoting
                // it beside period-average phase currents (which can look balanced) reads
                // as a contradiction unless the averaging is made explicit.
                finding: `Current imbalance reaches ${iUnb.toFixed(1)}% at the 95th percentile`
                    + (iUnbAvg !== null ? ` (period average ${iUnbAvg.toFixed(1)}%)` : '')
                    + `, against a ${I_UNBALANCE_GUIDE}% guideline.${phases ? ` Period-average phase currents:${phases.replace(' (', ' ').replace(' average)', '')}.` : ''}`
                    + ` Imbalance varies through the day — the peak figure is what determines thermal stress.`
                    + (tIUnb.trend !== 'NO_BASELINE' ? ` ${tIUnb.note}` : ''),
                mechanism: loadSide
                    ? `Incoming voltage is balanced (${vUnb?.toFixed(2)}%) while current is not, which places the fault inside your installation: single-phase loads are unevenly distributed across the three phases. The most heavily loaded phase carries excess current, overheating that conductor and the corresponding motor windings, while the neutral carries the resulting return current.`
                    : `Both voltage and current are unbalanced, indicating the imbalance originates upstream of your installation and is being imposed by the supply.`,
                action: loadSide
                    ? 'Rebalance single-phase loads across L1/L2/L3 at the distribution board. This is typically a few hours of electrician time and requires no new equipment. Re-measure afterwards to confirm.'
                    : 'Log a supply quality complaint with your utility, attaching this report as evidence, and request a supply-side investigation.',
                standard: 'NEMA MG-1 / SANS 10142-1 — load balancing and conductor loading',
            });
        }

        // Motor thermal stress from voltage unbalance (NEMA MG-1).
        if (vUnb !== null && vUnb > 1) {
            const derate = nemaDerate(vUnb);
            const tempRise = windingTempRisePct(vUnb);
            risks.push({
                key: 'motor_derating',
                severity: vUnb > 3 ? 'CRITICAL' : vUnb > 2 ? 'HIGH' : 'MEDIUM',
                title: 'Motors are being thermally derated by voltage unbalance',
                finding: `Voltage unbalance of ${vUnb.toFixed(2)}% requires motors to be derated to ${(derate * 100).toFixed(0)}% of nameplate capacity.`,
                mechanism: `Unbalanced voltage induces a negative-sequence current that produces almost no useful torque but significant heat. Winding temperature rise increases by roughly 2 × (unbalance)², so ${vUnb.toFixed(2)}% unbalance implies about a ${tempRise.toFixed(0)}% increase in temperature rise. Insulation life halves for approximately every 10 °C of additional winding temperature.`,
                action: `Derate affected motors to ${(derate * 100).toFixed(0)}% of nameplate, or correct the unbalance at source. Thermal-image the largest motors under load to confirm.`,
                standard: 'NEMA MG-1 §14.35 — effect of unbalanced voltage on induction motors',
            });
        }

        // Voltage excursions → drive/contactor trip exposure.
        if (dips > 0 || swells > 0) {
            risks.push({
                key: 'voltage_excursions',
                severity: dips + swells > n * 0.05 ? 'HIGH' : 'MEDIUM',
                title: 'Voltage excursions are exposing sensitive equipment to trips',
                finding: `${dips.toLocaleString()} readings below ${V_MIN} V and ${swells.toLocaleString()} above ${V_MAX} V during the observation window.`,
                mechanism: 'Variable-speed drives, PLCs and contactor coils commonly drop out at 80–90% of nominal voltage. Each excursion risks an unplanned stop, and repeated events accelerate wear on contactors and DC-bus capacitors in drives.',
                action: 'Correlate these timestamps with any unexplained production stops. Where critical loads are affected, evaluate ride-through (UPS on controls) or a voltage regulator on the incomer.',
                standard: 'NRS 048-2 — voltage dips and swells; IEC 61000-4-34 equipment immunity',
            });
        }

        // Harmonic resonance risk — the post-solar-installation blind spot.
        if (thdP95 !== null && thdP95 > 5) {
            risks.push({
                key: 'harmonic_resonance',
                severity: thdP95 > THD_LIMIT ? 'HIGH' : 'MEDIUM',
                title: 'Harmonic distortion threatens capacitors and transformers',
                finding: `Voltage THD at ${thdP95.toFixed(2)}% (95th percentile).`,
                mechanism: 'Harmonic currents cause additional heating in transformers and cables, and can excite a resonance with power-factor-correction capacitors — amplifying the distortion and destroying capacitor stages. This risk rises sharply after inverter-based generation (solar/BESS) is commissioned.',
                action: 'Before adding or replacing PF correction, confirm capacitors are detuned (reactor-fitted). Investigate the dominant harmonic order to identify the source.',
                standard: 'NRS 048-2 / IEEE 519 — harmonic control',
            });
        }

        // Harmonic CURRENT — a different finding from the voltage-distortion risk
        // above. Voltage THD is largely what the supply delivers; current
        // distortion is what this installation draws, so it is the client's to
        // fix and the neutral-loading question is a safety one.
        if (tddKnowable && tddP95! > TDD_STRICTEST) {
            risks.push({
                key: 'current_distortion',
                severity: tddP95! > TDD_LOOSEST ? 'HIGH' : 'MEDIUM',
                title: 'Harmonic current is loading the neutral and transformer',
                finding: `Current distortion reaches ${thdIP95!.toFixed(1)}% THD-I at the 95th percentile under load`
                    + `, roughly ${tddP95!.toFixed(1)}% expressed as demand distortion against the ${iPeak?.toFixed(0) ?? '—'} A peak.`
                    + (tThdI.trend !== 'NO_BASELINE' ? ` ${tThdI.note}` : ''),
                mechanism: 'Non-linear loads — variable-speed drives, LED drivers, switch-mode power supplies, UPS rectifiers — '
                    + 'draw current in pulses rather than as a sinusoid. The triplen orders (3rd, 9th, 15th) do not cancel in the '
                    + 'neutral of a three-phase system but add, so the neutral can end up carrying more current than any phase '
                    + 'while typically being sized for less. Separately, transformer eddy-current losses rise roughly with the '
                    + 'square of harmonic order, so the same kVA of distorted load runs the transformer hotter than clean load would.',
                action: 'Measure the neutral current directly and compare it against the neutral conductor rating — that is the '
                    + 'immediate safety question, and it is a clamp-meter check. Confirm whether the supply transformer is K-rated '
                    + 'or derated for harmonic duty. To settle compliance definitively, obtain the supply transformer rating and '
                    + 'the utility fault level: together they give the short-circuit ratio that fixes which IEEE 519 limit applies here.',
                standard: 'IEEE 519 — harmonic control; SANS 10142-1 — neutral conductor sizing',
            });
        }

        // Power factor exposure — quantified where a tariff is known.
        if (pfAvg !== null && pfAvg < PF_TARGET && peakKw !== null) {
            const kvarNeeded = peakKw * (Math.tan(Math.acos(pfAvg)) - Math.tan(Math.acos(PF_TARGET)));
            risks.push({
                key: 'power_factor',
                severity: pfAvg < 0.90 ? 'HIGH' : 'MEDIUM',
                title: 'Power factor is below the utility target',
                finding: `Average power factor ${pfAvg.toFixed(3)} against a ${PF_TARGET} target. Correcting to ${PF_TARGET} at the measured ${peakKw.toFixed(0)} kW peak requires approximately ${Math.max(0, kvarNeeded).toFixed(0)} kVAr of compensation.`,
                mechanism: 'Low power factor means a higher apparent (kVA) demand for the same useful work, inflating kVA-based demand charges and, on most SA tariffs, triggering a reactive energy penalty. It also loads cables and transformers with current that does no work.',
                action: `Install or repair power-factor correction sized at roughly ${Math.max(0, kvarNeeded).toFixed(0)} kVAr. If PF correction is already installed, a falling power factor at unchanged load usually indicates failed capacitor stages — inspect the bank.`,
                standard: 'Utility tariff condition; SANS 10142-1 for installation',
            });
        }

        // ── Scores: separate what the utility owns from what the client owns ──
        // Power factor and current distortion are things the INSTALLATION does,
        // not things the supply delivers. Scoring them against the utility would
        // contradict the whole point of separating the two responsibilities.
        const supplyChecks = parameters.filter(
            p => p.key !== 'power_factor' && p.key !== 'current_distortion'
        );
        const supplyScore = Math.round(
            supplyChecks.reduce((acc, p) =>
                acc + (p.status === 'PASS' ? 100 : p.status === 'WARN' ? 65 : p.status === 'FAIL' ? 20 : 70), 0
            ) / supplyChecks.length
        );

        let installScore = 100;
        for (const risk of risks) {
            installScore -= risk.severity === 'CRITICAL' ? 35
                          : risk.severity === 'HIGH'     ? 22
                          : risk.severity === 'MEDIUM'   ? 12 : 5;
        }
        installScore = Math.max(0, installScore);

        // Any open equipment risk downgrades the verdict — reporting "all clear"
        // while findings are outstanding would misrepresent the assessment.
        const anyFail = parameters.some(p => p.status === 'FAIL');
        const verdict: ComplianceReport['verdict'] =
            anyFail ? 'NON_COMPLIANT'
            : risks.length > 0 ? 'COMPLIANT_WITH_RISK'
            : 'COMPLIANT';

        const verdict_note =
            verdict === 'NON_COMPLIANT'
                ? 'The incoming supply breaches one or more NRS 048-2 compatibility levels. This is the utility\'s responsibility — the evidence in this report supports a formal quality-of-supply complaint.'
            : verdict === 'COMPLIANT_WITH_RISK'
                ? 'The incoming supply meets NRS 048-2. However, conditions inside your installation are placing measurable stress on connected equipment — these are within your control to correct.'
                : 'Supply quality and installation conditions are both within accepted limits for the observation period. Continued monitoring will detect degradation before it causes failure.';

        // ── Period-over-period movement — the case for staying subscribed ──
        // Current imbalance is tracked here too (it drives the headline risk even
        // though it isn't a compliance parameter).
        const degradingItems: string[] = parameters
            .filter(pm => pm.trend === 'DEGRADING')
            .map(pm => pm.label);
        if (tIUnb.trend === 'DEGRADING') degradingItems.push('Phase current imbalance');

        const improvingItems: string[] = parameters
            .filter(pm => pm.trend === 'IMPROVING')
            .map(pm => pm.label);
        if (tIUnb.trend === 'IMPROVING') improvingItems.push('Phase current imbalance');

        const trend_summary = !hasBaseline
            ? `This is the first full ${days}-day assessment for this meter. From the next report onward, every parameter will be tracked against this baseline so that gradual deterioration is caught long before it causes a failure.`
            : degradingItems.length > 0
                ? `${degradingItems.length} parameter${degradingItems.length > 1 ? 's have' : ' has'} deteriorated measurably versus the previous ${days} days: ${degradingItems.join(', ')}. Deterioration between periods is the earliest available warning of a developing fault — investigate before it becomes a failure.`
            : improvingItems.length > 0
                // Name what improved — a bare "conditions improved" next to a table of
                // "stable" rows reads as a contradiction.
                ? `Improved versus the previous ${days} days: ${improvingItems.join(', ')}. Nothing deteriorated. Where remedial work was carried out, this is the measured evidence that it worked.`
                : `All parameters are holding steady against the previous ${days} days. No developing faults detected.`;

        return {
            meter_id: meterId,
            meter_name: meta.rows[0].meter_name,
            site_name:  meta.rows[0].site_name,
            period_days: days,
            readings: n,
            from: r.t_from,
            to: r.t_to,
            verdict,
            verdict_note,
            parameters,
            risks: risks.sort((a, b) => {
                const rank = { CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3 };
                return rank[a.severity] - rank[b.severity];
            }),
            supply_score: supplyScore,
            install_score: installScore,
            has_baseline: hasBaseline,
            trend_summary,
            degrading: degradingItems,
        };
    } finally {
        client.release();
    }
}
